import { Group, PlaneGeometry, Mesh, Texture, Color, Vector3, Euler, Matrix4 } from 'three/webgpu';
import { MeshBasicNodeMaterial, mix, texture, uv, positionWorld, mul, vec3, float, vec4, varNode } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import { createMSDFText } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 * @property {{imageUrl:string}} assets
 * @property {{textContent:string}} textContent
 * @property {{palette:Record<string,string>}} colors
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>Texture} textureLoader
 * @property {{[key:string]:(target:THREE.Object3D,params:any)=>void}} primitives
 * @property {{atlas: any}} fontAtlas
 */

/**
 * Creates a CTA label node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // Root group
  const root = new Group();

  // Apply cinematic primitives if any (none for this spec)
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives[primitive.name];
      if (fn) fn(root, primitive.params);
    }
  }

  // === Textured Plane ===
  // Plane geometry respecting texture aspect (512x320 -> 1.6:1)
  const planeWidth = 1.6;
  const planeHeight = 1.0;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);

  // Load texture synchronously
  const tex = ctx.textureLoader(config.assets.imageUrl);
  tex.flipY = false; // UV orientation for webgpu

  // Material using NodeMaterial system
  const material = new MeshBasicNodeMaterial();
  material.colorNode = mix(
    varNode('color', new Color(config.colors.surface)),
    texture(tex).rgb,
    float(1.0)
  );

  // Optional subtle grain effect using TSL (simple noise placeholder)
  const grain = mul(
    uv().add(positionWorld().xy),
    float(100.0)
  );
  const grainFactor = float(0.02);
  material.opacityNode = varNode('opacity', float(1.0)).sub(grainFactor.mul(uv().r));

  const planeMesh = new Mesh(geometry, material);
  planeMesh.position.set(0, 0, 0);
  root.add(planeMesh);

  // === MSDF Text ===
  const text = config.textContent?.trim() ?? '';
  if (text) {
    const textColor = new Color(config.colors.ink);
    const textMesh = createMSDFText({
      text,
      fontAtlas: ctx.fontAtlas,
      color: textColor,
      // Approximate size; 42px at typical screen maps to ~0.4 scene units
      size: 0.42,
      // Atlas region (0,0,512,320) already defined inside fontAtlas
    });

    // Center text on plane and lift slightly forward
    textMesh.position.set(0, 0, 0.01);
    root.add(textMesh);
  }

  // === Transform from config ===
  if (config.position) {
    root.position.set(config.position.x, config.position.y, config.position.z);
  }
  if (config.rotation) {
    root.rotation.set(
      config.rotation.x,
      config.rotation.y,
      config.rotation.z
    );
  }
  if (config.scale) {
    root.scale.set(config.scale.x, config.scale.y, config.scale.z);
  }

  // === UserData Handlers & Cleanup ===
  root.userData.handlers = {};

  const timelines = [];

  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    if (tex && tex instanceof Texture) tex.dispose();

    // Dispose any text resources if provided by the utility
    if (root.children) {
      for (const child of root.children) {
        if (child.geometry) child.geometry.dispose?.();
        if (child.material) child.material.dispose?.();
      }
    }

    // Kill GSAP timelines
    for (const tl of timelines) tl.kill();
    timelines.length = 0;
  };

  return root;
}
